cat > $d/LayerDependencyTests.cs <<'E'
using System.Reflection;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Application;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private const string Prefix = "PaymentAuthorization.";

    private static readonly string[] TechnicalAssemblies =
    [
        "System.Net.Http", "System.Net.Primitives", "System.Net.Sockets", "System.Data",
        "System.Data.Common", "System.Diagnostics.Process", "System.IO.FileSystem",
    ];

    private static IEnumerable<string> References(Assembly assembly) =>
        assembly.GetReferencedAssemblies().Select(a => a.Name!);

    [Fact]
    public void Domain_depends_on_no_other_layer()
    {
        var offending = References(typeof(Money).Assembly).Where(n => n.StartsWith(Prefix));

        Assert.Empty(offending);
    }

    [Fact]
    public void Application_depends_only_on_Domain()
    {
        var offending = References(typeof(AuthorizePayment).Assembly)
            .Where(n => n.StartsWith(Prefix) && n != "PaymentAuthorization.Domain");

        Assert.Empty(offending);
    }

    [Theory]
    [InlineData(typeof(Money))]
    [InlineData(typeof(AuthorizePayment))]
    public void Business_layers_do_not_use_technical_assemblies(Type anchor)
    {
        var offending = References(anchor.Assembly).Where(TechnicalAssemblies.Contains);

        Assert.Empty(offending);
    }
}
